// ============================================================
// EXTRAIRE MESSAGE WhatsApp (CORRIGÉ - plus d'auto-référence)
// ============================================================
const data = $input.first().json;

// Structure WhatsApp Cloud API
const messages  = data?.messages  || [];
const contacts  = data?.contacts  || [];
const message   = messages[0]     || {};
const contact   = contacts[0]     || {};

// Ignorer les messages non-texte (images, audio, stickers...)
const msgType = message?.type || '';
if (msgType && msgType !== 'text') {
  // Retourner une instruction de réponse générique
  return [{
    json: {
      skip: true,
      msg: '',
      phoneFrom: message?.from || '',
      clientName: contact?.profile?.name || message?.from || '',
      waId: contact?.wa_id || message?.from || '',
      messageId: message?.id || '',
      msgType
    }
  }];
}

// Texte du message
const msg = message?.text?.body?.trim() || '';

// Ignorer si message vide
if (!msg) return [];

// Ignorer les accusés de réception (ok, d'accord, merci, etc.)
const ACK_PATTERNS = [
  /^(ok|okay|oké|oke)$/i,
  /^(d'?accord|daccord|dacord)$/i,
  /^(merci|merci\s+beaucoup|thanks|thx)$/i,
  /^(bien|bien\s+reçu|bien\s+recu|reçu|recu)$/i,
  /^(👍|🙏|✅|😊|🫡)+$/,
  /^(super|parfait|nickel|top|bonne?)$/i,
  /^(yes|yep|oui|ouii|ouais)$/i,
  /^(compris|c'est\s+noté|noté|note)$/i
];
const isAck = ACK_PATTERNS.some(p => p.test(msg));
if (isAck) return [];

// Infos client
const phoneFrom  = message?.from || '';
const clientName = contact?.profile?.name || phoneFrom;
const waId       = contact?.wa_id || phoneFrom;
const messageId  = message?.id || '';

return [{
  json: {
    skip: false,
    msg,
    phoneFrom,
    clientName,
    waId,
    messageId,
    msgType: 'text'
  }
}];

// ============================================================
// PRÉPARER CONTEXTE + INTENTION
// ============================================================
const msgData  = $('Extraire message').first().json;
const apiResp  = $input.first().json;

const msg        = msgData.msg        || '';
const clientName = msgData.clientName || 'Client';
const phoneFrom  = msgData.phoneFrom  || '';
const waId       = msgData.waId       || phoneFrom;

// Commandes récupérées
const orders = Array.isArray(apiResp?.orders)
  ? apiResp.orders
  : Array.isArray(apiResp)
    ? apiResp
    : [];

// Traduction des statuts
const statusLabels = {
  'en_attente' : '⏳ En préparation',
  'disponible' : '✅ Prête à récupérer',
  'retiree'    : '📦 Récupérée',
  'annulee'    : '❌ Annulée'
};

let ordersContext = '';
if (orders.length === 0) {
  ordersContext = 'Aucune commande trouvée pour ce numéro de téléphone.';
} else {
  ordersContext = orders.slice(0, 5).map(o => {
    const status  = statusLabels[o.status] || o.status || 'Inconnu';
    const total   = parseFloat(o.total_price || o.total || 0);
    const deposit = parseFloat(o.deposit || 0);
    const reste   = Math.max(0, total - deposit);
    const items   = Array.isArray(o.products) && o.products.length
      ? o.products.map(p => `${p.name}${p.quantity > 1 ? ' x' + p.quantity : ''}`).join(', ')
      : (o.description || o.items || '—');
    return `• Commande #${o.order_number}\n  Statut  : ${status}\n  Articles: ${items}\n  Total   : ${total.toFixed(2)}€ | Acompte versé: ${deposit.toFixed(2)}€ | Reste à payer: ${reste.toFixed(2)}€`;
  }).join('\n\n');
}

const systemPrompt = `Tu es l'assistant automatique de notre boutique. Tu réponds aux clients en français sur WhatsApp.\nSois concis, chaleureux et professionnel (max 3 phrases).\n\nClient : ${clientName}\nTéléphone : ${phoneFrom}\n\n=== Commandes du client ===\n${ordersContext}\n===========================\n\nRègles importantes :\n- Si le client demande le statut → donne le statut exact de sa commande\n- Si la commande est "disponible" → dis-lui de venir récupérer et rappelle le reste à payer\n- Si aucune commande trouvée → demande-lui son numéro de commande\n- Ne jamais inventer d'informations non présentes ci-dessus\n- Réponds uniquement en français\n- Pour TOUTE autre question (prix, disponibilité produit, livraison, réclamation, ou toute demande hors commande) → réponds exactement : "Pour toute autre demande, contactez notre support directement sur WhatsApp : +22890226491 😊"\n- Ne réponds JAMAIS à des questions hors commandes (politique, actualité, conseils, etc.)`;

return [{
  json: {
    msg,
    phoneFrom,
    clientName,
    waId,
    systemPrompt,
    ordersCount: orders.length
  }
}];

// ============================================================
// EXTRAIRE RÉPONSE IA
// ============================================================
const openaiData  = $input.first().json;
const contextData = $('Préparer contexte + intention').first().json;

// Réponse OpenAI
const aiReply = openaiData?.choices?.[0]?.message?.content?.trim()
  || 'Désolé, je n\'ai pas pu traiter votre demande. Veuillez nous contacter directement.';

// Log tokens utilisés
const tokensUsed = openaiData?.usage?.total_tokens || 0;
console.log(`[IA] Tokens utilisés: ${tokensUsed} | Client: ${contextData.clientName}`);

return [{
  json: {
    aiReply,
    phoneFrom  : contextData.phoneFrom,
    waId       : contextData.waId,
    clientName : contextData.clientName,
    tokensUsed
  }
}];

// Message non-texte → répondre poliment
const data = $('Extraire message').first().json;
const msgType = data?.msgType || 'inconnu';

const typeLabels = {
  'image'    : 'image',
  'audio'    : 'message vocal',
  'video'    : 'vidéo',
  'document' : 'document',
  'sticker'  : 'sticker'
};
const typeLabel = typeLabels[msgType] || 'message';

return [{
  json: {
    aiReply   : `Bonjour ! Je ne peux traiter que les messages texte pour le moment. Merci d'écrire votre question en texte 🙏`,
    phoneFrom : data.phoneFrom,
    waId      : data.waId,
    clientName: data.clientName
  }
}];
